@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <urn:example:agent:pipeline> ;
            sh:resultMessage "An agent should have an rdfs:label, given directly or generated during uplift." ;
            sh:resultPath rdfs:label ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "An agent should have an rdfs:label, given directly or generated during uplift." ;
                    sh:minCount 1 ;
                    sh:path rdfs:label ;
                    sh:severity sh:Warning ] ] .

